# fill_joe_hye_tech.ps1
# Bulk-fills the Joe Hye Tech test answers into a running local Accredo instance
# Run this from inside accredo_package, with flask run already active in another window

$baseUrl = "http://127.0.0.1:5000"
$email = "joehye@gmail.com"
$password = "TestPass123!"
$applicationId = 1   # change this if your application has a different ID

Write-Host "Logging in..." -ForegroundColor Cyan
$session = $null
$loginBody = @{ email = $email; password = $password } | ConvertTo-Json
try {
    Invoke-RestMethod -Uri "$baseUrl/api/auth/login" -Method Post -ContentType "application/json" -Body $loginBody -SessionVariable session | Out-Null
    Write-Host "Login successful." -ForegroundColor Green
} catch {
    Write-Host "Login failed: $_" -ForegroundColor Red
    exit 1
}

$answers = @(
    @{ id = '0-A-1'; text = 'Joe Hye Technical Institute, LLC was founded in 2018 by Joseph Hye to address a growing need for accessible, career-focused technology training in the Washington, DC metropolitan area. The school began enrolling students in its Software Development Certificate program in January 2019, and added the IT Support & Network Administration Certificate program in September 2020 in response to strong regional employer demand for entry-level network and help-desk technicians. Since its founding, the school has graduated multiple cohorts in both programs and has maintained continuous, uninterrupted operation. The school first became eligible to apply for ACCSC accreditation after completing two full years of continuous operation and graduating its first cohort from its longest program.' }
    @{ id = '0-C-1'; text = 'Joe Hye Tech''s mission is to prepare students for entry-level employment in software development and information technology through rigorous, hands-on technical instruction, industry-aligned curricula, and dedicated career support. The school''s primary educational objectives are: (1) to equip graduates with the practical coding, systems, and troubleshooting skills employers in the DC-metro technology sector require; (2) to maintain small class sizes that allow for individualized instruction and mentorship; and (3) to connect graduates with employment opportunities through an active employer-partner network.' }
    @{ id = '0-C-2'; text = 'The Software Development Certificate program was developed in response to labor market data from the DC Department of Employment Services showing sustained demand for junior developers in the region''s growing technology and government-contracting sectors. The IT Support & Network Administration program was added after informal surveys of local employers (including several DC-based managed service providers) identified a shortage of qualified entry-level help-desk and network support technicians. Both programs'' curricula were developed with input from an advisory committee of local IT hiring managers and are reviewed annually against current job postings and industry certification objectives (CompTIA A+/Network+ for IT Support; industry-standard web and application frameworks for Software Development).' }
    @{ id = '0-C-4'; text = 'Joe Hye Tech does not currently maintain contractual training arrangements with outside businesses or government agencies; all instruction is delivered directly to students enrolled in the school''s own certificate programs. [Edit this if Joe Hye Tech does have such arrangements.]' }
    @{ id = '0-E-1'; text = 'Joe Hye Tech is licensed to operate as a postsecondary institution by the District of Columbia Office of the State Superintendent of Education (OSSE), Higher Education Licensure Commission. The school maintains compliance with applicable DC business licensing requirements, fire and safety codes enforced by the DC Department of Buildings, and federal requirements including FERPA (student records privacy) and, where applicable, Title IV program requirements. [Confirm actual DC licensing body and license number before submitting.]' }
    @{ id = 'I-A-1'; text = 'Joe Hye Tech is managed under a direct-oversight model in which the School Director has full-time, on-site responsibility for day-to-day academic and administrative operations, reporting directly to the owner, Joseph Hye. The School Director is supported by a Lead Instructor for each program area and an Admissions/Student Services Coordinator. Weekly management meetings review enrollment, academic progress, budget-to-actual performance, and student services activity, ensuring that operational issues are identified and addressed promptly. This flat, on-site management structure allows for rapid decision-making and consistent day-to-day oversight appropriate to the school''s current size and program offerings.' }
    @{ id = 'I-A-3'; text = 'All management staff are required to review and sign an annual acknowledgment of the school''s Code of Conduct and institutional policies, which explicitly address ethical recruitment and admissions practices, accurate advertising, and compliance with ACCSC''s Standards of Accreditation. The School Director conducts quarterly compliance check-ins with each department lead, and any identified gaps are documented and remediated through a corrective-action process tracked by the School Director.' }
    @{ id = 'I-A-4'; text = 'Administrative and operational policies are reviewed annually by the School Director in coordination with department leads, and updated as needed in response to regulatory changes, ACCSC standard updates, or operational lessons learned. Proposed policy changes are documented, reviewed against applicable state and ACCSC requirements, and communicated to staff via a written policy update memo before taking effect.' }
    @{ id = 'I-A-5'; text = 'Management staff participate in ACCSC''s annual training workshops and webinars relevant to their roles, and the School Director attends the ACCSC Institute for Professional Development when offered. Internally, the school holds quarterly professional development sessions covering topics such as student retention strategies, regulatory compliance updates, and effective advising practices.' }
    @{ id = 'I-A-7'; text = 'The current average tenure of the school''s management and administrative staff is approximately 3 years, reflecting the relative recency of the school''s founding. This tenure level has supported stable day-to-day operations and consistent institutional knowledge, and the school''s retention efforts (including competitive compensation review and professional development opportunities) are aimed at maintaining and extending staff tenure as the institution matures. [Replace with actual figure.]' }
    @{ id = 'I-B-1'; text = 'Joe Hye Tech conducts an annual institutional self-assessment covering management effectiveness, fiscal health, educational program quality, and student services, drawing on data including student satisfaction surveys, graduate outcomes, employer feedback, and financial performance against budget. Findings are compiled into an annual improvement plan reviewed by the School Director and owner, with specific action items assigned and tracked to completion.' }
    @{ id = 'I-C-1'; text = 'Joe Hye Tech is funded through a combination of student tuition revenue and owner capital contributions, with sufficient working capital maintained to cover a minimum of three months of operating expenses at all times. The school''s financial structure is designed to ensure uninterrupted delivery of instruction and support services regardless of short-term enrollment fluctuations.' }
    @{ id = 'I-C-2'; text = 'The School Director prepares an annual operating budget in consultation with the owner, based on projected enrollment, historical expense data, and planned program investments. Actual performance is reviewed monthly against budget, with variances of more than 10% investigated and addressed. The budget is formally revised at mid-year if enrollment or expense trends materially diverge from initial projections.' }
    @{ id = 'I-C-3'; text = 'Working capital is allocated to ensure adequate staffing levels, up-to-date instructional equipment (including current-generation development workstations and networking lab hardware), facility maintenance, and a reserve sufficient to support currently enrolled students through completion of their programs even in the event of an enrollment downturn.' }
    @{ id = 'I-D-1'; text = 'a. Tuition, fees, and charges are itemized in the school catalog and enrollment agreement, provided to every applicant prior to enrollment. b. Tuition for the Software Development Certificate is $14,500; tuition for the IT Support & Network Administration Certificate is $9,800. Both include required course materials. c. The school does not currently offer tuition discounts. [Edit if applicable.] d. No institutional grants or scholarships are currently offered. [Edit if applicable.] e. The school reserves the right to change tuition for future enrollment periods with 60 days'' written notice; tuition is locked for the duration of a student''s enrollment agreement once signed.' }
    @{ id = 'I-F-1'; text = 'Yes. "Joe Hye Technical Institute" is registered and approved as the school''s legal operating name with the DC Office of the State Superintendent of Education and the DC Department of Consumer and Regulatory Affairs. [Confirm actual registration status.]' }
    @{ id = 'I-G-2'; text = 'Joe Hye Tech operates from a single leased facility in Washington, DC comprising two dedicated computer lab classrooms (each equipped with 16 student workstations), a networking lab with rack-mounted equipment for hands-on IT support training, a student lounge/study area, and administrative offices. The facility totals approximately 4,500 square feet and is sized to comfortably support current enrollment of up to 60 students across both programs, with capacity for planned enrollment growth.' }
    @{ id = 'II-A-2'; text = 'Both of Joe Hye Tech''s programs were designed using a backward-design methodology beginning with target job competencies identified through employer advisory input and current industry certification objectives, then mapped into a sequenced curriculum of foundational, applied, and capstone coursework. Each program culminates in a portfolio project or capstone assessment that mirrors real-world job tasks in the relevant field.' }
    @{ id = 'II-A-3'; text = 'The Software Development Certificate program is 900 clock hours delivered over 40 weeks, organized into progressive modules covering programming fundamentals, front-end and back-end web development, databases, and a final capstone project. The IT Support & Network Administration Certificate is 600 clock hours over 26 weeks, covering hardware/software troubleshooting, networking fundamentals, systems administration, and help-desk practicum. Program lengths were determined based on the scope of competencies required for entry-level employment in each field and are consistent with comparable programs regionally.' }
    @{ id = 'II-A-5'; text = 'Instructional materials include current-edition industry-standard textbooks and online learning platforms, updated on a rolling basis to reflect current technology. Lab equipment includes current-generation development workstations, networking hardware (routers, switches, patch panels) for hands-on configuration exercises, and access to industry-standard development and virtualization software.' }
    @{ id = 'II-B-1'; text = 'Both certificate programs are composed entirely of technical and occupationally related coursework directly aligned to job-ready competencies in software development and IT support, respectively, consistent with the certificate (non-degree) format of these programs.' }
    @{ id = 'II-B-2'; text = '100% of instructional hours in both certificate programs are technical and occupationally related, exceeding the required minimum, as the programs are designed exclusively around direct job-skill development rather than general education content.' }
    @{ id = 'III-A-2'; text = 'The Software Development program is led by a Lead Instructor with professional software development experience and a bachelor''s degree in Computer Science; the IT Support & Network Administration program is led by a Lead Instructor holding current CompTIA Network+ and Security+ certifications and prior professional IT support management experience. Both program heads have full-time, on-site responsibility for curriculum oversight and instructional quality within their respective programs.' }
    @{ id = 'III-A-5'; text = 'Faculty are formally evaluated twice annually through a combination of classroom observation by the School Director, student course evaluations, and review of student outcomes (completion and competency assessment pass rates) in courses they teach. Results are discussed in individual feedback sessions and inform professional development planning.' }
    @{ id = 'III-A-6'; text = 'Faculty are provided an annual professional development allowance to maintain relevant industry certifications and attend technology-focused continuing education, ensuring instructional content remains current with evolving software development and IT support practices.' }
    @{ id = 'III-A-7'; text = 'The school verifies faculty work experience through direct contact with prior employers as part of the hiring process, with documentation of verification calls or written confirmation retained in each faculty member''s personnel file.' }
    @{ id = 'III-A-8'; text = 'Official transcripts are requested directly from the issuing institution for each faculty member prior to their start date and retained in their personnel file; hiring is contingent on receipt of transcripts confirming credentials required for the teaching assignment.' }
    @{ id = 'III-A-9'; text = 'The current average tenure of Joe Hye Tech''s faculty is approximately 2.5 years, consistent with the school''s founding date. The school has experienced minimal faculty turnover to date, which has supported curriculum continuity and instructional quality. [Replace with actual figure.]' }
    @{ id = 'III-B-1'; text = 'The school maintains a maximum student-to-instructor ratio of 16:1 in lab-based courses, consistent with the workstation capacity of each classroom, ensuring adequate individualized instruction and hands-on support.' }
    @{ id = 'III-B-2'; text = 'New faculty complete a structured onboarding program covering instructional methodology, classroom management, and use of the school''s learning management system, followed by a mentored teaching period with an experienced instructor before assuming independent classroom responsibility.' }
    @{ id = 'IV-A-1'; text = 'Joe Hye Tech''s recruitment efforts consist primarily of digital advertising (targeted social media and search advertising), participation in DC-area career and community events, and referrals from current students and graduates. The school does not engage in door-to-door or high-pressure recruitment tactics of any kind.' }
    @{ id = 'IV-A-2'; text = 'Recruitment materials and initial inquiry conversations are designed to surface each prospective student''s career goals and background before any admissions conversation occurs, so that only individuals genuinely suited to a technology career path are encouraged to proceed through the admissions process. Admissions staff compensation is not tied to enrollment volume, removing incentive for high-pressure recruitment.' }
    @{ id = 'IV-A-3'; text = 'The school''s recruitment practices comply with DC consumer protection law and applicable FTC guidance regarding truthful advertising, and all recruitment personnel are trained annually on these requirements as part of the onboarding described in Section IV-A-5.' }
    @{ id = 'IV-A-4'; text = '[Fill in with actual staff names/titles — e.g., "Admissions Coordinator: (name), responsible for initial inquiry response and campus tours."]' }
    @{ id = 'IV-A-5'; text = 'Admissions personnel are selected for strong communication skills and genuine interest in student success rather than sales experience. All new admissions staff complete a two-week training program covering ACCSC advertising and recruitment standards, the school''s code of conduct, and accurate program representation, before conducting any prospective-student conversations independently.' }
    @{ id = 'IV-A-7'; text = 'The School Director periodically reviews recorded or logged admissions interactions and conducts spot-check follow-up calls with recently enrolled students to confirm the accuracy and completeness of information provided during recruitment. Any identified discrepancies are addressed through direct coaching and, if necessary, corrective action.' }
    @{ id = 'IV-B-1'; text = 'All advertising and promotional content is drafted by the School Director or designated staff and reviewed against ACCSC''s advertising standards and the school''s actual catalog data before publication, with a documented approval step required prior to any material going live.' }
    @{ id = 'IV-B-2'; text = 'All claims regarding program outcomes, career opportunities, or salary information are cross-checked against the school''s actual, current graduate outcomes data before use in any advertising material, and unsupported or aspirational claims are not permitted.' }
    @{ id = 'IV-B-3'; text = 'The school does not use "Help Wanted" or employment-styled advertisements to recruit students; all recruitment advertising clearly identifies the school and its educational programs as such.' }
    @{ id = 'IV-B-4'; text = 'Any student or graduate testimonials or images used in advertising are obtained with signed written consent, and testimonials reflect genuine, verifiable individual experiences rather than generalized or implied outcomes.' }
    @{ id = 'IV-B-5'; text = 'Any salary information referenced in advertising is drawn directly from the school''s documented graduate employment records or verifiable third-party labor market data (e.g., Bureau of Labor Statistics), never from unverified or aspirational figures.' }
    @{ id = 'IV-C-1'; text = 'The school catalog and enrollment agreement are reviewed and updated annually by the School Director to ensure accuracy of program offerings, tuition, policies, and required disclosures, with legal review conducted for any substantive policy changes.' }
    @{ id = 'IV-C-2'; text = 'A current catalog is provided to every applicant, in electronic or physical form, prior to enrollment, with signed acknowledgment of receipt retained in the student''s file.' }
    @{ id = 'IV-C-3'; text = 'Every enrolled student executes a written enrollment agreement prior to the start of instruction, signed by both the student and an authorized school representative, with a copy provided to the student at the time of signing.' }
    @{ id = 'IV-C-4'; text = 'Prior to enrollment, applicants review and acknowledge in writing the school''s tuition, refund, and cancellation policies, as well as their rights and responsibilities as a student, as part of the enrollment agreement process.' }
    @{ id = 'IV-C-5'; text = 'Current graduation and graduate employment rate data is published in the school catalog and made available to prospective students upon request prior to enrollment, updated annually.' }
    @{ id = 'V-A-1'; text = 'Admission to Joe Hye Tech requires a high school diploma or equivalent, completion of an admissions interview, and a passing score on a basic aptitude assessment appropriate to the chosen program. Admission decisions are made by the Admissions Coordinator based solely on these documented criteria, applied consistently to all applicants.' }
    @{ id = 'V-A-2'; text = 'Enrollment occurs on a rolling basis with new cohorts beginning quarterly. Applicants who meet all admissions requirements and complete the enrollment agreement are admitted; readiness is determined through the aptitude assessment and admissions interview described above, not through subjective judgment.' }
    @{ id = 'V-A-3'; text = 'All applicants are evaluated against the same documented admissions checklist regardless of background, and admissions decisions are reviewed periodically by the School Director to confirm consistent application of criteria across all applicants.' }
    @{ id = 'V-A-4'; text = 'Required documentation includes proof of high school diploma or equivalent (transcript or diploma copy), government-issued photo ID, and a signed enrollment agreement. Each item is checked against a standardized admissions checklist maintained in the student''s file.' }
    @{ id = 'V-A-5'; text = 'Academic documents from foreign institutions are required to be evaluated by a NACES-member credential evaluation service and translated into English by a certified translator before being accepted as satisfying admissions requirements.' }
    @{ id = 'V-A-6'; text = 'In rare cases where a standard diploma/equivalent cannot be produced, the school may accept alternative documentation (e.g., an ability-to-benefit assessment) consistent with applicable state and federal requirements, reviewed and approved by the School Director on a case-by-case basis.' }
    @{ id = 'V-A-7'; text = 'Joe Hye Tech admits students without regard to race, color, national origin, sex, age, or disability, consistent with applicable federal and DC anti-discrimination law; admissions decisions are based solely on the documented criteria described above.' }
    @{ id = 'V-A-8'; text = '[Describe a real recent change if one exists — e.g., "The school recently standardized its admissions checklist to reduce processing time and ensure consistent document collection across all applicants." Edit or remove if none applicable.]' }
    @{ id = 'VI-A-1'; text = 'Joe Hye Tech provides academic support through weekly instructor office hours and peer tutoring sessions, and non-academic support through career coaching, resume/interview preparation, and referrals to community resources (housing, transportation, childcare assistance) as needed. The Student Services Coordinator serves as the primary point of contact for all student support needs.' }
    @{ id = 'VI-A-2'; text = 'Student services are scaled to the school''s current enrollment of approximately 60 students, with a dedicated full-time Student Services Coordinator supplemented by faculty office hours, ensuring accessible support without excessive wait times or caseloads.' }
    @{ id = 'VI-A-3'; text = 'The adequacy of student services is assessed annually through student satisfaction surveys and utilization tracking (e.g., frequency of advising sessions, tutoring attendance), with staffing adjustments considered if utilization data indicates unmet demand.' }
    @{ id = 'VI-A-4'; text = 'Each student advising interaction is logged in the school''s student information system, noting date, topic discussed, and any follow-up actions, creating a comprehensive record accessible to relevant staff while maintaining student privacy.' }
    @{ id = 'VI-B-1'; text = 'The school maintains a complete educational record for each enrolled student including enrollment agreement, attendance records, grades/competency assessments, and any advising or disciplinary documentation, stored in the school''s student information system with restricted staff access.' }
    @{ id = 'VI-B-3'; text = 'Students may request official transcripts in writing (or via the school''s online request form); transcripts are processed and issued within 5 business days, consistent with the school''s published policy and applicable state requirements.' }
    @{ id = 'VI-B-4'; text = 'Student records are maintained in a secure, access-controlled student information system with role-based permissions, and physical documents (where applicable) are stored in locked file cabinets accessible only to authorized administrative staff.' }
    @{ id = 'VI-B-5'; text = 'Record maintenance practices comply with FERPA and applicable DC recordkeeping requirements, including retention periods and secure disposal procedures for records that have reached the end of their required retention period.' }
    @{ id = 'VI-C-1'; text = 'The Student Services Coordinator provides resume review, mock interviews, job search coaching, and direct introductions to the school''s network of employer partners for all students approaching program completion.' }
    @{ id = 'VI-C-2'; text = 'A graduate is classified as employed in field when their job title and primary job duties align directly with the competencies taught in their completed program, verified through documentation described in VI-C-3.' }
    @{ id = 'VI-D-1'; text = 'Students may submit complaints in writing to the School Director, who reviews and responds within 10 business days. The complaint procedure, including the option to escalate to ACCSC if not resolved at the institutional level, is disclosed in the school catalog and enrollment agreement.' }
    @{ id = 'VI-D-2'; text = 'Each complaint is logged, investigated by the School Director (or a neutral staff member if the complaint involves the Director), and tracked to resolution with written documentation of the outcome provided to the student.' }
    @{ id = 'VI-D-3'; text = '[State actual complaint history and outcomes — e.g., "Since the school''s founding, complaints received have been resolved within the stated 10-business-day timeframe, with no unresolved complaints outstanding."]' }
    @{ id = 'VI-D-4'; text = '[List actual complaints and resolutions, or state "No complaints have been received during this period" if accurate.]' }
    @{ id = 'VII-A-1'; text = 'The school''s academic integrity policy, published in the catalog, prohibits plagiarism and unauthorized collaboration on individual assessments, with violations addressed through a documented progressive-discipline process ranging from a warning to dismissal for repeated violations.' }
    @{ id = 'VII-A-2'; text = 'Students receive progress reports at the midpoint and end of each course module, covering grades, attendance, and competency assessment results, delivered both electronically and reviewed in person during advising sessions.' }
    @{ id = 'VII-A-3'; text = 'The school''s SAP policy requires students to maintain a minimum 70% cumulative grade average and 80% attendance rate; students falling below these thresholds are placed on academic probation with a documented improvement plan and additional advising support.' }
    @{ id = 'VII-A-4'; text = 'Students are required to maintain minimum 80% attendance in each course; attendance is tracked daily, and students falling below this threshold receive escalating outreach from faculty and the Student Services Coordinator to identify and address barriers to attendance.' }
    @{ id = 'VII-A-5'; text = 'Students who fail to meet SAP requirements after a documented probationary period are subject to termination from the program, with written notice provided and information on the appeal process included, consistent with the school''s published policy.' }
    @{ id = 'VII-B-1'; text = 'Educational quality is assessed through course-level competency assessment pass rates, end-of-program capstone evaluation results, graduate employment outcomes, and employer satisfaction feedback, compiled annually into the institutional self-assessment described in Section I-B-1.' }
    @{ id = 'VII-B-2'; text = 'The Student Services Coordinator contacts graduates at 3, 6, and 12 months post-completion to document employment status, which informs both individual continued job-search support and the school''s aggregate outcomes reporting.' }
)

$successCount = 0
$failCount = 0

foreach ($item in $answers) {
    $body = @{ narrative_text = $item.text } | ConvertTo-Json
    try {
        Invoke-RestMethod -Uri "$baseUrl/api/applications/$applicationId/responses/$($item.id)" -Method Put -ContentType "application/json" -Body $body -WebSession $session | Out-Null
        Write-Host "  OK: $($item.id)" -ForegroundColor Green
        $successCount++
    } catch {
        Write-Host "  FAILED: $($item.id) - $_" -ForegroundColor Red
        $failCount++
    }
}

Write-Host ""
Write-Host "Done. $successCount saved, $failCount failed." -ForegroundColor Cyan

Write-Host "Marking Distance Education (IX), ESL (V-E), and Graduate Degrees (V-D) as Not Applicable..." -ForegroundColor Cyan
$naSubsections = @(
    @{ section = "IX"; subsection = "A" }, @{ section = "IX"; subsection = "B" },
    @{ section = "IX"; subsection = "C" }, @{ section = "IX"; subsection = "D" },
    @{ section = "IX"; subsection = "E" }, @{ section = "IX"; subsection = "F" },
    @{ section = "IX"; subsection = "G" }, @{ section = "IX"; subsection = "H" },
    @{ section = "V"; subsection = "E" }, @{ section = "V"; subsection = "D" }
)
foreach ($sub in $naSubsections) {
    $naBody = @{ not_applicable = $true } | ConvertTo-Json
    try {
        Invoke-RestMethod -Uri "$baseUrl/api/applications/$applicationId/subsections/$($sub.section)/$($sub.subsection)/not-applicable" -Method Put -ContentType "application/json" -Body $naBody -WebSession $session | Out-Null
        Write-Host "  N/A set: $($sub.section)-$($sub.subsection)" -ForegroundColor Green
    } catch {
        Write-Host "  FAILED to set N/A: $($sub.section)-$($sub.subsection) - $_" -ForegroundColor Yellow
    }
}

Write-Host ""
Write-Host "Checking completeness..." -ForegroundColor Cyan
$completeness = Invoke-RestMethod -Uri "$baseUrl/api/applications/$applicationId/completeness" -WebSession $session
Write-Host "Completed: $($completeness.completed) / $($completeness.total_required) ($($completeness.percentage)%)" -ForegroundColor Cyan